// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        bool expected = c.approvedToLog(caller);
        bool result = c.logRegisteredPubkey(bytes32(0), bytes32(0));
        // vm.prank must be used to simulate the caller for both calls
        vm.prank(caller);
        expected = c.approvedToLog(caller);
        vm.prank(caller);
        result = c.logRegisteredPubkey(bytes32(0), bytes32(0));
        assertTrue(result == expected, "logRegisteredPubkey return value mismatch");
    }
}

